  let a = repeated(p, pitch);
  let shifted = p - pitch * 0.5;
  let b = repeated(shifted, pitch);
  let own = select(b, a, dot(a, a) < dot(b, b));
  let middle = p - own;
  return vec4f(own, round(middle.x * 2.0), round(middle.y / 0.8660254));
