  let hair = mix(vec3f(0.02, 0.015, 0.012), vec3f(0.3, 0.29, 0.27), grey);
  let cloth = select(vec3f(0.02, 0.022, 0.03), vec3f(0.1, 0.09, 0.04), khaki);
  let red = vec3f(0.4, 0.01, 0.008);
  let gilt = vec3f(0.55, 0.36, 0.06);

